parameters.text:
=Escribe un artículo original para “Curioso” basado en la siguiente pauta editorial:

Título de referencia:
{{$json.titulo}}

Ángulo editorial:
{{$json.angulo_editorial}}

Impacto real en la vida cotidiana:
{{$json.impacto_real}}

Por qué este tema es curioso:
{{$json.por_que_es_curioso}}

Tipo de contenido:
{{$json.tipo_contenido}}

parameters.jsCode:
function stripCodeFences(text) {
  if (!text) return '';
  return text
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();
}

const raw =
  $json.output ??
  $json.text ??
  $json.result ??
  '';

if (!raw) {
  throw new Error('AI Agent no devolvió output');
}

let data;
try {
  data = JSON.parse(stripCodeFences(raw));
} catch (err) {
  throw new Error('No se pudo parsear JSON del AI Agent. Output recibido:\n' + raw);
}

if (!Array.isArray(data)) {
  throw new Error('El JSON devuelto no es un array');
}

return data.map((pauta, index) => ({
  json: {
    ...pauta,
    pauta_index: index + 1
  }
}));

return items.map((item, index) => {
  const article =
    item.json.output ??
    item.json.text ??
    '';

  if (!article || article.length < 500) {
    throw new Error(`El redactor no generó un artículo válido en el item ${index + 1}`);
  }

  return {
    json: {
      ...item.json,
      articulo: article
    }
  };
});

// texto del agente
const raw = $json.output;

// quitar ```json y ```
let cleaned = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// convertir a JSON
const parsed = JSON.parse(cleaned);

// devolver cada clip como item
return parsed.clips.map(c => ({
  json: {
    id: c.id,
    prompt: c.prompt,
    voiceover: c.voiceover
  }
}));

